mkdir -p /app/bin /app/out; cat > /app/bin/hourly.py <<'EOF'
import sys, os, re, json, math
from datetime import datetime, timedelta, timezone

QS = ['temp', 'rh', 'pres', 'wspd', 'wdir', 'rain']
RANGE = {'temp': (-50, 60), 'rh': (0, 100), 'pres': (870, 1085),
         'wspd': (0, 60), 'wdir': (0, 360), 'rain': (0, 5000)}
EPOCH = datetime(1970, 1, 1)
DIR_RE = re.compile(r'^#\s*([a-z]+)\s*:(.*)$')


def conv(q, unit, v):
    if unit == 'tips' or unit.startswith('tips:'):
        return v * float(unit.split(':', 1)[1])
    t = {
        ('temp', 'degF'): lambda x: (x - 32) * 5 / 9,
        ('temp', 'K'): lambda x: x - 273.15,
        ('rh', 'frac'): lambda x: x * 100,
        ('pres', 'kPa'): lambda x: x * 10,
        ('pres', 'inHg'): lambda x: x * 33.8638866667,
        ('pres', 'mmHg'): lambda x: x * 1.33322387415,
        ('wspd', 'kmh'): lambda x: x / 3.6,
        ('wspd', 'kn'): lambda x: x * 1852 / 3600,
        ('wspd', 'mph'): lambda x: x * 0.44704,
    }.get((q, unit))
    return t(v) if t else v


def parse_time(s):
    s = s.strip().replace('T', ' ')
    d = datetime.strptime(s, '%Y-%m-%d %H:%M:%S')
    return int((d - EPOCH).total_seconds())


def parse_tz(s):
    s = s.strip()
    if s == 'Z':
        return 0
    sign = -1 if s[0] == '-' else 1
    h, m = s[1:].split(':')
    return sign * (int(h) * 3600 + int(m) * 60)


def missing(f):
    f = f.strip()
    if f == '' or f == '---' or f.lower() == 'nan':
        return True
    return re.fullmatch(r'-9999(\.0*)?', f) is not None


def read_file(path):
    with open(path, 'rb') as fh:
        text = fh.read().decode('utf-8')
    if text.startswith('\ufeff'):
        text = text[1:]
    info = {'station': None, 'upload': 0, 'interval': None, 'tz': 0}
    cols = None
    units = {}
    rows = []
    syncs = []
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if not line.strip():
            continue
        if line[0] == '#':
            m = DIR_RE.match(line)
            if not m:
                continue
            k, v = m.group(1), m.group(2).strip()
            if k == 'station':
                info['station'] = v
            elif k == 'upload':
                info['upload'] = int(v)
            elif k == 'interval':
                info['interval'] = int(v)
            elif k == 'tz':
                info['tz'] = parse_tz(v)
            elif k == 'columns':
                cols = [c.strip() for c in v.split(',')]
            elif k == 'units':
                for p in v.split():
                    if '=' in p:
                        a, b = p.split('=', 1)
                        units[a] = b
            elif k == 'sync':
                d = {}
                for p in v.split():
                    if '=' in p:
                        a, b = p.split('=', 1)
                        d[a] = b
                if 'logger' in d and 'ref' in d:
                    lt = parse_time(d['logger']) - info['tz']
                    ref = parse_time(d['ref'].rstrip('Z'))
                    syncs.append((lt, ref - lt))
            continue
        if cols is None:
            continue
        fields = [f.strip() for f in line.split(',')]
        vals = {}
        t = None
        for c, f in zip(cols, fields):
            if c == 'time':
                t = parse_time(f) - info['tz']
            elif c in RANGE and not missing(f):
                try:
                    v = conv(c, units.get(c, ''), float(f))
                except ValueError:
                    continue
                lo, hi = RANGE[c]
                if lo <= v <= hi:
                    vals[c] = v
        if t is not None:
            rows.append((t, vals))
    return info, rows, syncs


def offset_at(sp, t):
    if not sp:
        return 0
    if t <= sp[0][0]:
        return sp[0][1]
    if t >= sp[-1][0]:
        return sp[-1][1]
    lo, hi = 0, len(sp) - 1
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if sp[mid][0] <= t:
            lo = mid
        else:
            hi = mid
    (t1, o1), (t2, o2) = sp[lo], sp[hi]
    if t == t1:
        return o1
    return o1 + ((o2 - o1) * (t - t1)) // (t2 - t1)


def fmt_hour(h):
    return (EPOCH + timedelta(seconds=h)).strftime('%Y-%m-%dT%H:00:00Z')


def main(indir, outfile):
    st = {}
    for name in sorted(os.listdir(indir)):
        p = os.path.join(indir, name)
        if not name.endswith('.log') or not os.path.isfile(p):
            continue
        info, rows, syncs = read_file(p)
        if info['station'] is None:
            continue
        s = st.setdefault(info['station'], {'interval': info['interval'], 'rows': {}, 'sync': {}})
        if s['interval'] is None:
            s['interval'] = info['interval']
        up = info['upload']
        for t, v in rows:
            old = s['rows'].get(t)
            if old is None or up >= old[0]:
                s['rows'][t] = (up, v)
        for t, o in syncs:
            old = s['sync'].get(t)
            if old is None or up >= old[0]:
                s['sync'][t] = (up, o)
    stations = []
    for sid in sorted(st):
        s = st[sid]
        if not s['rows']:
            continue
        iv = s['interval']
        sp = sorted((t, v[1]) for t, v in s['sync'].items())
        crow = []
        for t, (up, v) in s['rows'].items():
            crow.append((t + offset_at(sp, t), v))
        crow.sort(key=lambda x: x[0])
        hour = lambda c: -((-c) // 3600) * 3600
        data = {}  # hour -> q -> list
        rain_inc = {}
        prev = None
        for c, v in crow:
            h = hour(c)
            d = data.setdefault(h, {q: [] for q in QS})
            for q, x in v.items():
                if q != 'wdir':
                    d[q].append(x)
            if 'wdir' in v:
                d['wdir'].append(v['wdir'] if v.get('wspd', 0) > 0 else None)
            if 'rain' in v:
                r = v['rain']
                if prev is not None and (c - prev[0]) * 2 <= 5 * iv:
                    inc = r - prev[1] if r >= prev[1] else r
                    rain_inc[h] = rain_inc.get(h, 0) + inc
                prev = (c, r)
        h0, h1 = hour(crow[0][0]), hour(crow[-1][0])
        expected = 3600 / iv
        hours = []
        h = h0
        while h <= h1:
            d = data.get(h)
            ent = {'hour': fmt_hour(h)}
            for q in QS:
                lst = d[q] if d else []
                n = len(lst)
                val = None
                if n and n * 4 >= expected * 3:
                    if q == 'wdir':
                        vs = [x for x in lst if x is not None]
                        if vs:
                            sx = sum(math.sin(math.radians(x)) for x in vs)
                            sy = sum(math.cos(math.radians(x)) for x in vs)
                            val = math.degrees(math.atan2(sx, sy)) % 360
                    elif q == 'rain':
                        val = rain_inc.get(h, 0)
                    else:
                        val = math.fsum(lst) / n
                if val is not None:
                    val = round(val, 2)
                    if val >= 360:
                        val = 0.0
                    val += 0.0
                ent[q] = {'value': val, 'n': n}
            hours.append(ent)
            h += 3600
        stations.append({'station': sid, 'interval_s': int(iv), 'hours': hours})
    with open(outfile, 'w') as f:
        json.dump({'stations': stations}, f, indent=1)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
